    launchAncestry: launchAncestryOf(fsImpl),
    requested,
    spellings: new Set([requested]),
    leafIsSymlink: false,
    trace: { stoppedAt: requested, sawReadlink: false, readlinkFailed: false, lastErrno: undefined },
  }
